<?php require 'config/auth.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$q=$pdo->prepare("SELECT id FROM users WHERE role='admin' LIMIT 1");$q->execute();if($q->fetch())$msg='Admin already exists.';else{$pdo->prepare("INSERT INTO users(role,name,email,username,password_hash,status) VALUES('admin',?,?,?,?, 'active')")->execute(['Placement Administrator',$_POST['email'],'admin',password_hash($_POST['password'],PASSWORD_DEFAULT)]);$id=$pdo->lastInsertId();$pdo->prepare('INSERT INTO admins(user_id) VALUES(?)')->execute([$id]);$msg='Admin created. Delete setup_admin.php now.';}}$page_title='Admin Setup';require 'config/header.php';?><div class="authcard" style="max-width:520px;margin:70px auto"><h2>Admin Setup</h2><p class="muted small">Use once after importing SQL. Default: admin@careerbridge.local / Admin@123</p><?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="fg"><label>Email</label><input class="control" type="email" name="email" value="admin@careerbridge.local" required></div><div class="fg"><label>Password</label><input class="control" type="password" name="password" value="Admin@123" required></div><button class="btn primary">Create Admin</button></form></div><?php require 'config/footer.php';?>
